import { useEffect, useId, useRef, useState } from "react";
import {
  Button,
  Card,
  EmptyState,
  Flex,
  Heading,
  Price,
  ProductMedia,
  QuantityInput,
  Text,
} from "@paraxe/react";
import {
  canChangeCartQuantity,
  cartSummaryRows,
  defaultCartLabels,
  isCartLineAvailable,
  sampleCartLines,
  sampleCartSummary,
  validateCart,
  type Cart01Props,
} from "../shared/cart";
import "../shared/cart.css";
export function Cart01({
  as: Tag = "main",
  headingLevel = "h1",
  eyebrow = "THE COLLECTION / YOUR BAG",
  title = "Your bag.",
  lines: suppliedLines,
  summary: suppliedSummary,
  currency = "GBP",
  locale = "en-GB",
  continueHref = "/shop",
  continueLabel = "Continue shopping",
  notice = "Sample products and prices are illustrative.",
  labels: suppliedLabels,
  canCheckout = true,
  changeQuantity,
  removeLine,
  checkout,
}: Cart01Props) {
  const lines = suppliedLines ?? sampleCartLines;
  const summary =
    suppliedSummary ??
    (suppliedLines === undefined ? sampleCartSummary : undefined);
  validateCart(lines, summary);
  const labels = { ...defaultCartLabels, ...suppliedLabels };
  const count = lines.reduce((sum, line) => sum + line.quantity, 0);
  const ready =
    !!lines.length &&
    !!summary &&
    lines.every(isCartLineAvailable) &&
    canCheckout;
  const [pendingAction, setPendingAction] = useState<
    "quantity" | "remove" | "checkout" | null
  >(null);
  const pending = pendingAction !== null;
  const [message, setMessage] = useState(""),
    [error, setError] = useState(false);
  const busy = useRef(false),
    root = useRef<HTMLElement>(null),
    focusRequest = useRef<{ id: string; index: number } | null>(null);
  const id = useId();
  const sectionHeading =
    headingLevel === "h1" ? "h2" : headingLevel === "h2" ? "h3" : "h4";
  const rowHeading =
    headingLevel === "h1" ? "h3" : headingLevel === "h2" ? "h4" : "h5";
  useEffect(() => {
    const request = focusRequest.current;
    if (pending || !request || lines.some((line) => line.id === request.id))
      return;
    const rows =
      root.current?.querySelectorAll<HTMLElement>("[data-cart-line]");
    const row = rows?.[Math.min(request.index, (rows?.length ?? 0) - 1)];
    const target =
      row?.querySelector<HTMLElement>(
        "input:not(:disabled),button:not(:disabled)",
      ) ?? root.current?.querySelector<HTMLElement>("[data-cart-heading]");
    target?.focus();
    focusRequest.current = null;
  }, [pending, lines]);
  async function act(
    kind: "quantity" | "remove" | "checkout",
    lineId?: string,
    quantity?: number,
  ) {
    if (busy.current) return;
    const line = lines.find((item) => item.id === lineId);
    if (
      kind === "quantity" &&
      (!line || !changeQuantity || !canChangeCartQuantity(line, quantity!))
    )
      return;
    if (kind === "remove" && (!line || !removeLine)) return;
    if (kind === "checkout" && (!ready || !checkout)) return;
    busy.current = true;
    setPendingAction(kind);
    setError(false);
    setMessage(kind === "checkout" ? labels.opening : labels.updating);
    try {
      if (kind === "quantity") await changeQuantity!(lineId!, quantity!);
      else if (kind === "remove") {
        await removeLine!(lineId!);
        focusRequest.current = {
          id: lineId!,
          index: lines.findIndex((item) => item.id === lineId),
        };
      } else await checkout!();
      setMessage(
        kind === "remove"
          ? labels.removed
          : kind === "checkout"
            ? labels.checkoutRequested
            : labels.updated,
      );
    } catch {
      setError(true);
      setMessage(kind === "checkout" ? labels.checkoutFailure : labels.failure);
    } finally {
      busy.current = false;
      setPendingAction(null);
    }
  }
  return (
    <Tag
      ref={root}
      className="cart01"
      aria-labelledby={`${id}-title`}
      aria-busy={pending || undefined}
    >
      <div className="cart01-inner">
        <Flex className="cart01-header" justify="between" wrap>
          <Flex direction="column" size="small">
            <Text className="cart01-eyebrow">{eyebrow}</Text>
            <Heading
              id={`${id}-title`}
              data-cart-heading
              tabIndex={-1}
              level={headingLevel}
              className="cart01-title"
            >
              {title}
            </Heading>
          </Flex>
          {continueHref && (
            <a className="cart01-continue" href={continueHref}>
              {continueLabel}
            </a>
          )}
        </Flex>
        {!lines.length ? (
          <div className="cart01-empty">
            <EmptyState
              actions={
                continueHref ? (
                  <a className="btn btn-primary btn-md" href={continueHref}>
                    {continueLabel}
                  </a>
                ) : undefined
              }
            >
              <Heading level={sectionHeading}>{labels.emptyTitle}</Heading>
              <Text tone="muted">{labels.emptyDescription}</Text>
            </EmptyState>
          </div>
        ) : (
          <Flex className="cart01-layout" align="start" fullWidth>
            <section className="cart01-items" aria-label={labels.items}>
              <Flex className="cart01-column-head" justify="between">
                <Text as="span">
                  {count} {count === 1 ? labels.item : labels.items}
                </Text>
                <Text as="span">{labels.lineTotal}</Text>
              </Flex>
              <Heading level={sectionHeading} className="commerce-sr-only">
                {labels.items}
              </Heading>
              <ol className="cart01-list">
                {lines.map((line, index) => (
                  <li key={line.id} data-cart-line>
                    <Flex className="cart01-line" align="start">
                      <div className="cart01-media">
                        <ProductMedia src={line.imageSrc} alt={line.imageAlt} />
                      </div>
                      <Flex className="cart01-line-info" direction="column">
                        <Heading
                          level={rowHeading}
                          className="cart01-product-name"
                        >
                          {line.href ? (
                            <a href={line.href}>{line.name}</a>
                          ) : (
                            line.name
                          )}
                        </Heading>
                        {line.variantLabel && (
                          <Text className="cart01-meta">
                            {line.variantLabel}
                          </Text>
                        )}
                        {line.unitAmount !== undefined && (
                          <p className="cart01-meta">
                            <Price
                              amount={line.unitAmount}
                              currency={currency}
                              locale={locale}
                            />{" "}
                            / {labels.each}
                          </p>
                        )}
                        {!isCartLineAvailable(line) && (
                          <Text className="cart01-unavailable">
                            {line.available === false || line.maxQuantity === 0
                              ? labels.unavailable
                              : labels.quantityUnavailable}
                          </Text>
                        )}
                        <Flex
                          className="cart01-line-actions"
                          align="center"
                          wrap
                        >
                          {isCartLineAvailable(line) ? (
                            <QuantityInput
                              id={`${id}-quantity-${index}`}
                              label={`${labels.quantity}: ${line.name}${line.variantLabel ? ` / ${line.variantLabel}` : ""}`}
                              hideLabel
                              modelValue={line.quantity}
                              max={line.maxQuantity}
                              size="small"
                              disabled={pending || !changeQuantity}
                              onModelValueChange={(value) =>
                                act("quantity", line.id, value)
                              }
                            />
                          ) : (
                            <Text className="cart01-meta">
                              {labels.quantity}: {line.quantity}
                            </Text>
                          )}
                          {removeLine && (
                            <Button
                              variant="text"
                              size="small"
                              disabled={pending}
                              aria-label={`${labels.remove}: ${line.name}${line.variantLabel ? ` / ${line.variantLabel}` : ""}`}
                              onActivate={() => act("remove", line.id)}
                            >
                              {labels.remove}
                            </Button>
                          )}
                        </Flex>
                      </Flex>
                      <div className="cart01-line-price">
                        <Price
                          amount={line.lineAmount}
                          currency={currency}
                          locale={locale}
                        />
                      </div>
                    </Flex>
                  </li>
                ))}
              </ol>
            </section>
            <Card as="aside" className="cart01-summary">
              <Heading level={sectionHeading} className="cart01-summary-title">
                {labels.summary}
              </Heading>
              {summary ? (
                <dl>
                  {cartSummaryRows(summary, labels).map((row) => (
                    <Flex
                      key={row.key}
                      className="cart01-summary-row"
                      justify="between"
                    >
                      <dt>{row.label}</dt>
                      <dd>
                        {row.amount === undefined ? (
                          labels.calculated
                        ) : (
                          <>
                            {row.key === "discount" ? "-" : ""}
                            <Price
                              amount={row.amount}
                              currency={currency}
                              locale={locale}
                            />
                          </>
                        )}
                      </dd>
                    </Flex>
                  ))}
                  <Flex
                    className="cart01-summary-row cart01-summary-total"
                    justify="between"
                  >
                    <dt>{labels.total}</dt>
                    <dd>
                      <Price
                        amount={summary.total}
                        currency={currency}
                        locale={locale}
                      />
                    </dd>
                  </Flex>
                </dl>
              ) : (
                <Text tone="muted">{labels.missingTotals}</Text>
              )}
              <Button
                width="full"
                disabled={pending || !ready || !checkout}
                onActivate={() => act("checkout")}
              >
                {pending
                  ? pendingAction === "checkout"
                    ? labels.opening
                    : labels.updating
                  : labels.checkout}
              </Button>
              {(!ready || !checkout) && (
                <p className="cart01-summary-note">
                  {!summary
                    ? labels.missingTotals
                    : !ready
                      ? labels.review
                      : labels.checkoutUnavailable}
                </p>
              )}
            </Card>
          </Flex>
        )}
        <p className="cart01-feedback" role={error ? "alert" : "status"}>
          {message}
        </p>
        {notice && <p className="cart01-notice">{notice}</p>}
      </div>
    </Tag>
  );
}

export interface Cart01Line {
  id: string;
  name: string;
  variantLabel?: string;
  imageSrc?: string;
  imageAlt: string;
  href?: string;
  quantity: number;
  maxQuantity?: number;
  available?: boolean;
  lineAmount: number;
  unitAmount?: number;
}
/** All amounts are app-supplied major currency units, not client-computed charges. */
export interface Cart01Summary {
  subtotal: number;
  total: number;
  shipping?: number;
  tax?: number;
  discount?: number;
}
export interface Cart01Labels {
  items: string;
  item: string;
  each: string;
  checkoutFailure: string;
  quantity: string;
  remove: string;
  lineTotal: string;
  summary: string;
  subtotal: string;
  shipping: string;
  tax: string;
  discount: string;
  total: string;
  calculated: string;
  checkout: string;
  updating: string;
  opening: string;
  updated: string;
  removed: string;
  checkoutRequested: string;
  failure: string;
  unavailable: string;
  quantityUnavailable: string;
  missingTotals: string;
  review: string;
  checkoutUnavailable: string;
  emptyTitle: string;
  emptyDescription: string;
}
export interface Cart01Props {
  as?: "main" | "section";
  headingLevel?: "h1" | "h2" | "h3";
  eyebrow?: string;
  title?: string;
  lines?: readonly Cart01Line[];
  summary?: Cart01Summary;
  currency?: string;
  locale?: string;
  continueHref?: string;
  continueLabel?: string;
  notice?: string;
  labels?: Partial<Cart01Labels>;
  canCheckout?: boolean;
  changeQuantity?: (lineId: string, quantity: number) => void | Promise<void>;
  removeLine?: (lineId: string) => void | Promise<void>;
  checkout?: () => void | Promise<void>;
}
export const defaultCartLabels: Cart01Labels = {
  items: "items",
  item: "item",
  each: "each",
  checkoutFailure: "Checkout could not be opened. Please try again.",
  quantity: "Quantity",
  remove: "Remove",
  lineTotal: "Total",
  summary: "Order summary",
  subtotal: "Subtotal",
  shipping: "Delivery",
  tax: "Tax",
  discount: "Discount",
  total: "Estimated total",
  calculated: "At checkout",
  checkout: "Continue to checkout",
  updating: "Updating your bag...",
  opening: "Opening checkout...",
  updated: "Your bag was updated.",
  removed: "Item removed.",
  checkoutRequested: "Checkout requested.",
  failure: "We couldn't update your bag. Please try again.",
  unavailable: "Currently unavailable.",
  quantityUnavailable: "This quantity is no longer available.",
  missingTotals: "Your total is currently unavailable.",
  review: "Review your bag before continuing.",
  checkoutUnavailable: "Checkout is unavailable in this preview.",
  emptyTitle: "Your bag is empty.",
  emptyDescription: "Find something that belongs in your everyday.",
};
export const sampleCartLines: readonly Cart01Line[] = [
  {
    id: "jersey-s",
    name: "Academy training jersey",
    variantLabel: "Training wear / S",
    imageSrc: "/paraxe/cart-01/jersey.svg",
    imageAlt: "Black training jersey",
    quantity: 1,
    maxQuantity: 8,
    unitAmount: 28,
    lineAmount: 28,
  },
  {
    id: "tote",
    name: "Everyday tote",
    variantLabel: "Accessories / One size",
    imageSrc: "/paraxe/cart-01/tote.svg",
    imageAlt: "Academy tote bag",
    quantity: 1,
    maxQuantity: 5,
    unitAmount: 18,
    lineAmount: 18,
  },
];
export const sampleCartSummary: Cart01Summary = { subtotal: 46, total: 46 };
export function validateCart(
  lines: readonly Cart01Line[],
  summary?: Cart01Summary,
): void {
  const ids = new Set<string>();
  let count = 0;
  for (const line of lines) {
    const id = line.id.trim();
    if (!id || ids.has(id))
      throw new RangeError("Cart lines require unique non-empty IDs.");
    ids.add(id);
    if (!Number.isSafeInteger(line.quantity) || line.quantity < 1)
      throw new RangeError("Cart quantity must be a positive safe integer.");
    count += line.quantity;
    if (!Number.isSafeInteger(count))
      throw new RangeError("Cart item count is too large.");
    if (
      line.maxQuantity !== undefined &&
      (!Number.isSafeInteger(line.maxQuantity) || line.maxQuantity < 0)
    )
      throw new RangeError(
        "Cart stock limits must be non-negative safe integers.",
      );
    if (!Number.isFinite(line.lineAmount) || line.lineAmount < 0)
      throw new RangeError(
        "Cart line amount is required and must be non-negative.",
      );
    for (const value of [line.lineAmount, line.unitAmount])
      if (value !== undefined && (!Number.isFinite(value) || value < 0))
        throw new RangeError("Cart amounts must be finite and non-negative.");
  }
  if (
    summary &&
    (!Number.isFinite(summary.subtotal) || !Number.isFinite(summary.total))
  )
    throw new RangeError("Cart subtotal and total are required.");
  if (summary)
    for (const value of [
      summary.subtotal,
      summary.total,
      summary.shipping,
      summary.tax,
      summary.discount,
    ])
      if (value !== undefined && (!Number.isFinite(value) || value < 0))
        throw new RangeError(
          "Cart summary amounts must be finite and non-negative.",
        );
}
export function isCartLineAvailable(line: Cart01Line): boolean {
  return (
    line.available !== false &&
    (line.maxQuantity === undefined || line.quantity <= line.maxQuantity)
  );
}
export function canChangeCartQuantity(
  line: Cart01Line,
  quantity: number,
): boolean {
  return (
    isCartLineAvailable(line) &&
    Number.isSafeInteger(quantity) &&
    quantity >= 1 &&
    (line.maxQuantity === undefined || quantity <= line.maxQuantity)
  );
}

export function cartSummaryRows(summary: Cart01Summary, labels: Cart01Labels) {
  return [
    { key: "subtotal", label: labels.subtotal, amount: summary.subtotal },
    { key: "shipping", label: labels.shipping, amount: summary.shipping },
    { key: "tax", label: labels.tax, amount: summary.tax },
    ...(summary.discount
      ? [{ key: "discount", label: labels.discount, amount: summary.discount }]
      : []),
  ];
}

.cart01 {
  --cart01-media-width: calc(var(--space-4) * 7);
  --cart01-summary-width: 31%;
  padding: var(--website-section-padding) var(--container-padding-lg);
  background: var(--background-primary);
  color: var(--text-primary);
  font-family: var(--font-family-body);
}
.cart01 *,
.cart01 *::before,
.cart01 *::after {
  box-sizing: border-box;
}
.cart01-inner {
  max-width: var(--container-max-width);
  margin-inline: auto;
}
.cart01 :is(h1, h2, h3, h4, h5, p, dl, dd) {
  margin: 0;
}
.cart01 .cart01-header {
  gap: var(--space-5);
  padding-block-end: var(--space-8);
  align-items: end;
}
.cart01 .cart01-eyebrow {
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-widest);
  font-weight: var(--font-weight-semibold);
}
.cart01 .cart01-title {
  font-size: var(--website-title-size);
  letter-spacing: var(--letter-spacing-tighter);
  line-height: var(--line-height-tight);
}
.cart01-continue {
  color: var(--text-primary);
  font-size: var(--typography-caption-size);
  text-underline-offset: var(--space-1);
}
.cart01 .cart01-layout {
  gap: var(--website-column-gap);
}
.cart01-items {
  flex: 1 1 0;
  min-width: 0;
}
.cart01 .cart01-column-head {
  padding-block: var(--space-4);
  border-block: var(--border-width-thin) solid var(--border-default);
  font-size: var(--typography-micro-size);
  letter-spacing: var(--letter-spacing-wide);
}
.cart01-list {
  list-style: none;
  margin: 0;
  padding: 0;
}
.cart01 .cart01-line {
  gap: var(--space-5);
  padding-block: var(--space-6);
  border-bottom: var(--border-width-thin) solid var(--border-default);
}
.cart01-media {
  flex: 0 0 var(--cart01-media-width);
}
.cart01-media .commerce-media {
  aspect-ratio: 1;
}
.cart01 .cart01-line-info {
  flex: 1 1 0;
  min-width: 0;
  gap: var(--space-3);
}
.cart01 .cart01-product-name {
  font-size: var(--typography-product-name-size);
  line-height: var(--line-height-snug);
  overflow-wrap: anywhere;
}
.cart01-product-name a {
  color: inherit;
  text-decoration: none;
}
.cart01-product-name a:hover {
  text-decoration: underline;
}
.cart01 .cart01-meta {
  font-size: var(--typography-caption-size);
  color: var(--text-muted);
  line-height: var(--line-height-relaxed);
}
.cart01 .cart01-line-actions {
  gap: var(--space-4);
  margin-block-start: var(--space-2);
}
.cart01 .cart01-line-price {
  flex: 0 1 22%;
  min-width: 0;
  text-align: end;
  font-size: var(--typography-product-price-size);
}
.cart01-line-price .price {
  white-space: normal;
  overflow-wrap: anywhere;
}
.cart01 .cart01-unavailable {
  font-size: var(--typography-caption-size);
  color: var(--color-danger);
}
.cart01 .cart01-summary {
  flex: 0 0 var(--cart01-summary-width);
  min-width: 0;
  position: sticky;
  top: var(--space-6);
}
.cart01 .cart01-summary-title {
  font-size: var(--font-size-lg);
  margin-block-end: var(--space-6);
}
.cart01 .cart01-summary-row {
  gap: var(--space-4);
  padding-block: var(--space-3);
  font-size: var(--typography-caption-size);
}
.cart01-summary-row dd {
  min-width: 0;
  text-align: end;
}
.cart01 .cart01-summary-total {
  margin-block-start: var(--space-4);
  padding-block: var(--space-5);
  border-block-start: var(--border-width-thin) solid var(--border-default);
  font-weight: var(--font-weight-semibold);
}
.cart01 .cart01-summary .btn {
  margin-block-start: var(--space-4);
  white-space: normal;
}
.cart01 .cart01-summary-note {
  margin-block-start: var(--space-4);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.cart01 .cart01-feedback {
  min-height: var(--space-6);
  margin-block-start: var(--space-4);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
}
.cart01-feedback[role="alert"] {
  color: var(--color-danger);
}
.cart01 .cart01-notice {
  margin-block-start: var(--space-6);
  font-size: var(--typography-caption-size);
  line-height: var(--line-height-relaxed);
  color: var(--text-muted);
}
.cart01-empty {
  padding-block: var(--space-12);
  border-block: var(--border-width-thin) solid var(--border-default);
}
.cart01 a:focus-visible {
  outline: var(--focus-ring-width) solid var(--focus-ring-color);
  outline-offset: var(--focus-ring-offset);
}
@media (max-width: 900px) {
  .cart01 {
    padding-inline: var(--container-padding);
  }
  .cart01 .cart01-layout {
    flex-direction: column;
  }
  .cart01-items,
  .cart01 .cart01-summary {
    width: 100%;
    flex-basis: auto;
    position: static;
  }
}
@media (max-width: 500px) {
  .cart01 {
    --cart01-media-width: calc(var(--space-4) * 4.5);
  }
  .cart01 .cart01-header {
    align-items: start;
  }
  .cart01 .cart01-line {
    gap: var(--space-3);
    flex-wrap: wrap;
  }
  .cart01 .cart01-line-price {
    flex-basis: 100%;
    text-align: start;
    padding-inline-start: calc(var(--cart01-media-width) + var(--space-3));
  }
}
